CREATE TABLE IF NOT EXISTS asset_intelligence_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES assets(id) ON DELETE CASCADE, trust_score numeric(6,2) NOT NULL DEFAULT 0, evidence_score numeric(6,2) NOT NULL DEFAULT 0, verification_score numeric(6,2) NOT NULL DEFAULT 0, risk_score numeric(6,2) NOT NULL DEFAULT 0, market_score numeric(6,2) NOT NULL DEFAULT 0, project_readiness_score numeric(6,2) NOT NULL DEFAULT 0, overall_score numeric(6,2) NOT NULL DEFAULT 0, intelligence_state text NOT NULL DEFAULT 'developing', rationale jsonb NOT NULL DEFAULT '{}'::jsonb, assessed_at timestamptz NOT NULL DEFAULT now());